-- Skip normal per-occurrence maintenance at the trigger boundary
-- while a native batch owns the transaction-local bulk scope.
-- Generated by src/vane/raw/generate-bulk-insert.py.
DROP TRIGGER vane_raw_occurrence_insert;
CREATE TRIGGER vane_raw_occurrence_insert AFTER INSERT ON vane_raw_occurrences
 WHEN NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) BEGIN
INSERT INTO vane_analytics_cells(site_id,day,kind,cell,n,timed,consented)
 SELECT site_id,day,kind,cell,1,timed,consented FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope)) WHERE 1
 ON CONFLICT(site_id,day,kind,cell) DO UPDATE SET n=n+1,timed=timed+excluded.timed,consented=consented+excluded.consented;
 INSERT INTO vane_analytics_identities(site_id,day,kind,cell,identity,n)
 SELECT site_id,day,kind,cell,identity,1 FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope)) WHERE visitor IS NOT NULL
 ON CONFLICT(site_id,day,kind,cell,identity) DO UPDATE SET n=n+1;
INSERT OR IGNORE INTO vane_visit_legacy(site,day,visitor) SELECT site,day,visitor FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND kind='pageview' AND visitor IS NOT NULL AND typeof(NEW.token)!='blob';
 INSERT OR IGNORE INTO vane_visit_dirty(site,day,visitor) SELECT c.site,c.day,c.visitor FROM vane_raw_contexts c JOIN vane_visit_legacy l USING(site,day,visitor) WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND c.kind='pageview' AND c.visitor IS NOT NULL;
 INSERT INTO vane_visit_work(raw_id,action,new_engaged,new_scroll) SELECT r.raw_id,'insert',r.engaged_at,r.scroll FROM vane_visit_raw r WHERE r.raw_id=NEW.raw_id AND r.at_offset IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND r.kind='pageview' AND r.visitor IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM vane_visit_dirty d WHERE d.site=r.site AND d.day=r.day AND d.visitor=r.visitor);
 END ;
CREATE TRIGGER vane_raw_occurrence_bulk_insert AFTER INSERT ON vane_raw_occurrences
 WHEN EXISTS(SELECT 1 FROM vane_visit_bulk_scope) BEGIN
 INSERT INTO vane_visit_work(raw_id,action)
 SELECT NEW.raw_id,'bulk' FROM vane_raw_groups g
 JOIN vane_raw_contexts c ON c.context=g.context
 WHERE g.group_id=NEW.group_id AND c.kind='pageview';
 END ;
